document.querySelectorAll('[data-video]').forEach(frame=>{const button=frame.querySelector('button');button.addEventListener('click',()=>{const embed=document.createElement('iframe');embed.src='https://drive.google.com/file/d/'+frame.dataset.video+'/preview';embed.title=button.getAttribute('aria-label');embed.allow='autoplay; fullscreen; encrypted-media; picture-in-picture';embed.allowFullscreen=true;embed.setAttribute('playsinline','');embed.setAttribute('webkit-playsinline','');embed.referrerPolicy='strict-origin-when-cross-origin';frame.replaceChildren(embed);});});
const header=document.querySelector('header');const toggle=document.querySelector('.nav-toggle');const navigation=document.getElementById('primary-navigation');if(header&&toggle&&navigation){header.classList.add('nav-ready');const closeMenu=()=>{header.classList.remove('nav-open');toggle.setAttribute('aria-expanded','false');};toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';header.classList.toggle('nav-open',open);toggle.setAttribute('aria-expanded',String(open));});navigation.addEventListener('click',event=>{if(event.target.closest('a'))closeMenu();});header.addEventListener('keydown',event=>{if(event.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'){closeMenu();toggle.focus();}});}

// Keep mobile pricing compact; preserve a visitor's choices until the layout crosses the breakpoint.
const pricingViewport=window.matchMedia("(max-width:700px)");const setPricingLayout=()=>document.querySelectorAll("details.pricing-category").forEach(category=>category.open=!pricingViewport.matches);setPricingLayout();pricingViewport.addEventListener("change",setPricingLayout);

// Dismiss the pricing menu when visitors leave it or press Escape.
const pricingMenu=document.querySelector('.pricing-menu');
if(pricingMenu){document.addEventListener('click',event=>{if(!pricingMenu.contains(event.target))pricingMenu.open=false;});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&pricingMenu.open){pricingMenu.open=false;pricingMenu.querySelector('summary').focus();}});}
